import { lazy, Suspense, useEffect, useMemo, useRef, useState } from 'react';
import { Activity, AlertTriangle, Archive, ArrowDownToLine, ArrowUpFromLine, Bell, Bug, Menu, X, RotateCcw, CalendarDays, CheckCircle2, CircleDot, ClipboardList, FlaskConical, Kanban, Languages, Moon, Plus, Search, Sun, BarChart3, Clock3, ShieldCheck, Zap, CheckCheck, Flag, GanttChartSquare, UserRound, Save } from 'lucide-react';
